--- desktop/gpui/fixtures/dossier-conversation/dbg_tmp.rs	
+++ desktop/gpui/fixtures/dossier-conversation/dbg_tmp.rs	
@@ -0,0 +1,33 @@
+#[path = "../../src/dossier_conversation/mod.rs"]
+pub mod dossier_conversation;
+extern crate twyne_desktop;
+fn main() {
+    let sample = r#"I love that direction. Who is the specific reader?
+
+DOSSIER: {
+  "brief": {
+    "workingTitle": "The Anatomy of Attention",
+    "format": "Essay",
+    "tone": "Sharp and lucid"
+  },
+  "confidence": {
+    "workingTitle": "high",
+    "format": "high",
+    "tone": "medium"
+  }
+}
+
+PROBE: {
+  "id": "probe-reader-type",
+  "kind": "choice",
+  "prompt": "Which reader should the opening target first?",
+  "options": ["Architect", "Worker", "Generalist"]
+}"#;
+    println!("sample len = {}", sample.len());
+    let seg = dossier_conversation::protocol::extract_tagged_json(sample, "DOSSIER").unwrap();
+    println!("DOSSIER seg start={} end={} val={}", seg.start, seg.end, seg.value);
+    let stripped = dossier_conversation::protocol::strip_tagged_json(sample, &seg);
+    println!("after dossier len = {}", stripped.len());
+    let seg2 = dossier_conversation::protocol::extract_tagged_json(&stripped, "PROBE").unwrap();
+    println!("PROBE seg start={} end={} val={}", seg2.start, seg2.end, seg2.value);
+}

