 const fs = require("node:fs");
 const crypto = require("node:crypto");
 const directory = "/home/diogenes/Projects/twyne/desktop/gpui/fixtures/math-write/mermaid";
 const profile = state.mermaidMathProfile || "original";
 await state.mermaidMathPage.waitForFunction(() => window.mermaidMathReady || window.mermaidMathError, {timeout:20000});
 const actual = await state.mermaidMathPage.evaluate(() => ({
   ready:window.mermaidMathReady, error:window.mermaidMathError,
   versions:window.mermaidMathVersions, rows:window.mermaidMathRows,
   editorRunSvg:window.mermaidEditorRunSvg, directHtml:window.mermaidDirectMathHtml,
-  fontStatus:document.fonts.status,
+  fontStatus:document.fonts.status,faces:window.mermaidMathFontFaces,fontLoads:window.mermaidMathFontLoads,
 }));
 if (!actual.ready || actual.error) throw new Error(actual.error || "Original renderer not ready.");
 const cdp = await getCDPSession({page:state.mermaidMathPage});
 await cdp.send("DOM.enable"); await cdp.send("CSS.enable");
 const {root} = await cdp.send("DOM.getDocument", {depth:0});
 const properties = ["font-family","font-size","font-weight","font-style","line-height","display","width","height","position","overflow","vertical-align","top"];
 async function observe(selector, fonts=false, index=0) {
   const locator = state.mermaidMathPage.locator(selector);
   if (await locator.count() <= index) return null;
   const {nodeIds} = await cdp.send("DOM.querySelectorAll", {nodeId:root.nodeId,selector});
   const nodeId = nodeIds[index];
   const {computedStyle} = await cdp.send("CSS.getComputedStyleForNode", {nodeId});
   const attributes = await cdp.send("DOM.getAttributes", {nodeId});
   let box = null; try { box = (await cdp.send("DOM.getBoxModel", {nodeId})).model; } catch {}
   let selectedFonts = null;
   if (fonts) selectedFonts = (await cdp.send("CSS.getPlatformFontsForNode", {nodeId})).fonts;
   return {
     selector,index,inspection:await inspect({locator:locator.nth(index),properties}),
     styles:Object.fromEntries(computedStyle.filter(({name})=>properties.includes(name)).map(({name,value})=>[name,value])),
     attributes:Object.fromEntries(Array.from({length:attributes.attributes.length/2},(_,i)=>[attributes.attributes[i*2],attributes.attributes[i*2+1]])),
     box, selectedFonts,
   };
 }
 const rows = [];
 for (const row of actual.rows) {
   const selector = `[data-mermaid-case="${row.id}"]`;
   const record = {...row, svgSha256:crypto.createHash("sha256").update(row.svg).digest("hex")};
   const svgFile = `${profile}-${row.id}.svg`;
   fs.writeFileSync(`${directory}/${svgFile}`,row.svg);
   record.svgFile = svgFile;
   record.inlineSvg = await observe(`${selector} .source-inline svg`);
   record.image = await observe(`${selector} .source-image img`);
   record.foreignObjects = [];
   const foCount = await state.mermaidMathPage.locator(`${selector} .source-inline foreignObject`).count();
   for (let index=0;index<foCount;index++) {
     record.foreignObjects.push(await observe(`${selector} .source-inline foreignObject`,false,index));
   }
   // Keep returned SVG attributes alongside transformed screen-space boxes.
   record.foreignObjectAttributes = [...row.svg.matchAll(/<foreignObject\b([^>]*)>/g)].map(match=>match[1]);
   record.katex = await observe(`${selector} .source-inline .katex`);
   record.mathml = await observe(`${selector} .source-inline math`,true);
   record.html = await observe(`${selector} .source-inline .katex-html`);
   record.base = await observe(`${selector} .source-inline .base`);
   record.strut = await observe(`${selector} .source-inline .strut`);
   record.sizing = await observe(`${selector} .source-inline .sizing`);
   record.glyph = await observe(`${selector} .source-inline .mathnormal`,true);
   record.label = await observe(`${selector} .source-inline .label`,true);
   record.embeddedStyles = [...row.svg.matchAll(/<style\b[^>]*>([\s\S]*?)<\/style>/g)].map(match=>match[1]);
   record.hasHtmlMath = row.svg.includes("katex-html");
   await state.mermaidMathPage.locator(selector).screenshot({path:`${directory}/${profile}-${row.id}.png`});
   rows.push(record);
 }
 const direct = {
   html:actual.directHtml,
   wrapper:await observe("#direct-math .twyne-math"),
   base:await observe("#direct-math .katex-base"),
   strut:await observe("#direct-math .katex-strut"),
   sizing:await observe("#direct-math .katex-sizing"),
 };
 fs.writeFileSync(`${directory}/${profile}-editor-run.svg`,actual.editorRunSvg);
 const editorRun = {
   svgFile:`${profile}-editor-run.svg`,
   svgSha256:crypto.createHash("sha256").update(actual.editorRunSvg).digest("hex"),
   svg:await observe(".source-run svg"),
   katex:await observe(".source-run .katex"),
   mathml:await observe(".source-run math",true),
   hasHtmlMath:actual.editorRunSvg.includes("katex-html"),
 };
 const output = {
-  provenance:"Actual published Source renderTwyneMermaid and initialize+run modules with original renderer/DOM; fixture-only whole stylesheet original/replacement/scoped variants. Separate image consumes the same returned SVG. No Source/app metadata edits or external requests.",
+  provenance:"Actual published Source renderTwyneMermaid and initialize+run modules with original renderer/DOM; fixture-only whole stylesheet original/replacement/scoped variants. Exact supplied KaTeX faces are loaded before render to isolate CSS from Mermaid cold font measurement. Separate image consumes the same returned SVG. No Source/app metadata edits or external requests.",
   profile,url:state.mermaidMathPage.url(),originalAppUrl:state.page?.url(),
-  versions:actual.versions,fontStatus:actual.fontStatus,
+  versions:actual.versions,fontStatus:actual.fontStatus,faces:actual.faces,fontLoads:actual.fontLoads,
   blockedOrigins:[...new Set(state.mermaidMathBlocked || [])],rows,direct,editorRun,
 };
 fs.writeFileSync(`${directory}/browser-${profile}.json`,JSON.stringify(output,null,2)+"\n");
 console.log({profile,versions:actual.versions,rows:rows.map(row=>({id:row.id,html:row.hasHtmlMath,svg:row.inlineSvg?.attributes?.viewBox,katex:row.katex?.styles,base:row.base?.styles?.display})),direct:{base:direct.base?.styles?.display,strut:direct.strut?.styles?.display,sizing:direct.sizing?.styles?.["font-size"]}});
 console.log(await getLatestLogs({page:state.mermaidMathPage,sinceLastCall:true}));

Index: desktop/gpui/src/app/page_coordinator.rs
===================================================================
--- desktop/gpui/src/app/page_coordinator.rs	
+++ desktop/gpui/src/app/page_coordinator.rs	
@@ -1,571 +1,793 @@
 use super::*;
 use gpui_kit::{EntityId, WeakEntity};
 use twyne_desktop::editor::view::{PaginationFallback, PaginationInfo};
 use twyne_desktop::page_furniture::{PageChromeGeometry, PageChromeText, PageMarginsPx};
 use twyne_desktop::workspace::PaginationMode;

 #[derive(Clone, Copy, Debug, PartialEq)]
 struct PageOwner {
     editor: EntityId,
     folio: Uuid,
     visit: u64,
 }

+#[cfg(all(test, feature = "ui-tests"))]
+mod tests {
+    use super::*;
+    use gpui_kit::{AnyWindowHandle, TestAppContext, size, test::TestWindowExt};
+    use tempfile::TempDir;
+
+    fn page_room(
+        cx: &mut TestAppContext,
+        layout: LayoutSettings,
+    ) -> (AnyWindowHandle, Entity<WritingRoom>, Arc<Store>, TempDir) {
+        let (handle, room, store, directory) = super::super::tests::room(cx);
+        let html = concat!(
+            "<p>Before the break<sup data-type=\"endnote\" data-endnote-text=\"A retained source.\"></sup></p>",
+            "<div data-type=\"page-break\" data-future=\"retained\"></div>",
+            "<p>After the deliberate break.</p>",
+        );
+        let path = store.root().join("Measured pages.html");
+        std::fs::write(&path, html).unwrap();
+        let document =
+            twyne_desktop::document_edit::apply_html(import_file(&path).unwrap(), html).unwrap();
+        let document = twyne_desktop::document_edit::apply_page_settings(
+            document,
+            layout,
+            "A retained running head".into(),
+            "A retained footer".into(),
+        )
+        .unwrap();
+        cx.update_window(handle, |_, window, cx| {
+            room.update(cx, |room, cx| {
+                assert!(room.add_document(document, window, cx));
+                room.set_write(window, cx);
+                room.desk.set_zen(false, false);
+                room.desk.drawer_open = false;
+                room.desk.board_open = false;
+                cx.notify();
+            });
+        })
+        .unwrap();
+        pump(cx, handle);
+        (handle, room, store, directory)
+    }
+
+    fn pump(cx: &mut TestAppContext, handle: AnyWindowHandle) {
+        for _ in 0..5 {
+            cx.update_window(handle, |_, window, cx| {
+                window.render_frame(cx);
+                window.simulate_next_frame(cx);
+            })
+            .unwrap();
+            cx.run_until_parked();
+        }
+    }
+
+    #[gpui_kit::test]
+    fn actual_host_measures_note_border_box_once_and_keeps_physical_pages_at_narrow_width(
+        cx: &mut TestAppContext,
+    ) {
+        let layout = LayoutSettings {
+            pagination: Some(PaginationMode::Paginated),
+            running_header: true,
+            ..LayoutSettings::default()
+        };
+        let (handle, room, _store, _directory) = page_room(cx, layout.clone());
+        let (editor, source, snapshot) = cx
+            .update_window(handle, |_, window, cx| {
+                let room = room.read(cx);
+                let editor = room.rich.clone().unwrap();
+                let state = room.pagination.borrow();
+                let info = state
+                    .info
+                    .as_ref()
+                    .expect("Host must accept the measured editor frame");
+                assert!(info.active);
+                assert_eq!(info.page_count, 2);
+                assert_eq!(
+                    f32::from(window.find("manuscript-page-canvas").bounds().size.width),
+                    816.
+                );
+                let notes_height = f32::from(window.find("manuscript-notes").bounds().size.height);
+                assert_eq!(
+                    state.tail_height, notes_height,
+                    "Tail excludes outer 40px margin and includes its border"
+                );
+                assert_eq!(
+                    window.find(("page-sheet", 1usize)).bounds().size.height,
+                    px(1056.)
+                );
+                let snapshot = editor.read(cx).snapshot();
+                (editor, room.active_document().body.clone(), snapshot)
+            })
+            .unwrap();
+        cx.simulate_window_resize(handle, size(px(620.), px(860.)));
+        pump(cx, handle);
+        cx.update_window(handle, |_, window, cx| {
+            let room = room.read(cx);
+            let state = room.pagination.borrow();
+            assert!(state.info.as_ref().unwrap().active);
+            assert_eq!(state.info.as_ref().unwrap().page_count, 2);
+            assert_eq!(
+                window.find("manuscript-page-canvas").bounds().size.width,
+                px(816.)
+            );
+            assert!(room.writing_scroll.max_offset().x >= px(196.));
+            assert_eq!(
+                state.tail_height,
+                f32::from(window.find("manuscript-notes").bounds().size.height)
+            );
+            assert_eq!(editor.read(cx).document(), &snapshot);
+            assert!(!editor.read(cx).can_undo());
+            assert_eq!(room.active_document().body, source);
+            assert_eq!(room.current_page_layout(cx), layout);
+        })
+        .unwrap();
+    }
+
+    #[gpui_kit::test]
+    fn unsupported_columns_keep_requested_settings_and_restore_real_sheet_chrome(
+        cx: &mut TestAppContext,
+    ) {
+        let layout = LayoutSettings {
+            pagination: Some(PaginationMode::Paginated),
+            columns: Some(2),
+            ..LayoutSettings::default()
+        };
+        let (handle, room, _store, _directory) = page_room(cx, layout.clone());
+        let (editor, snapshot) = cx
+            .update_window(handle, |_, window, cx| {
+                let editor = room.read(cx).rich.clone().unwrap();
+                let snapshot = editor.read(cx).snapshot();
+                room.update(cx, |room, cx| {
+                    let state = room.pagination.borrow();
+                    assert!(!state.info.as_ref().unwrap().active);
+                    assert_eq!(
+                        state.fallback(),
+                        Some(PaginationFallback::UnsupportedColumns)
+                    );
+                    assert_eq!(room.current_page_layout(cx), layout);
+                    assert!(window.find("pagination-status").bounds().size.height > px(0.));
+                    drop(state);
+                    let mut restored = layout.clone();
+                    restored.columns = Some(1);
+                    room.compositor
+                        .as_ref()
+                        .unwrap()
+                        .update(cx, |view, cx| view.set_layout(restored, window, cx));
+                    cx.notify();
+                });
+                (editor, snapshot)
+            })
+            .unwrap();
+        pump(cx, handle);
+        cx.update_window(handle, |_, window, cx| {
+            let room = room.read(cx);
+            assert!(room.pagination.borrow().info.as_ref().unwrap().active);
+            assert_eq!(room.current_page_layout(cx).columns, Some(1));
+            assert_eq!(
+                window.find("manuscript-page-canvas").bounds().size.width,
+                px(816.)
+            );
+            assert_eq!(editor.read(cx).document(), &snapshot);
+            assert!(!editor.read(cx).can_undo());
+        })
+        .unwrap();
+    }
+
+    #[gpui_kit::test]
+    fn rejected_sheet_stays_latched_across_its_own_events_and_retries_after_genuine_input(
+        cx: &mut TestAppContext,
+    ) {
+        let layout = LayoutSettings {
+            pagination: Some(PaginationMode::Paginated),
+            ..LayoutSettings::default()
+        };
+        let (handle, room, _store, _directory) = page_room(cx, layout);
+        cx.update_window(handle, |_, _, cx| {
+            let room = room.read(cx);
+            let mut state = room.pagination.borrow_mut();
+            let candidate = state.candidate.clone().unwrap();
+            let mut info = state.info.clone().unwrap();
+            // The library's native-shaper test covers generating this failure.
+            // Here the synthetic receipt isolates the host's retry boundary.
+            info.active = false;
+            info.fallback = Some(PaginationFallback::UnstableFloatGeometry);
+            assert!(state.accept(&candidate, info.clone()));
+            state.begin(candidate.clone());
+            assert!(state.rejected.is_some());
+            info.generation += 1;
+            info.fallback = Some(PaginationFallback::Continuous);
+            assert!(state.accept(&candidate, info));
+            assert_eq!(
+                state.fallback(),
+                Some(PaginationFallback::UnstableFloatGeometry)
+            );
+            let mut changed = candidate.clone();
+            changed.revision += 1;
+            state.begin(changed);
+            assert!(state.rejected.is_none());
+            assert!(
+                state.info.is_none(),
+                "An inactive old frame must not prevent the genuine retry"
+            );
+            assert!(
+                !state.accept(
+                    &candidate,
+                    room.rich
+                        .as_ref()
+                        .unwrap()
+                        .read(cx)
+                        .pagination_info()
+                        .unwrap()
+                )
+            );
+        })
+        .unwrap();
+    }
+}
+
 #[derive(Clone, Debug, PartialEq)]
