     pub fn hydrate_session_from_draft(
         session: &mut ConversationSession,
         draft: DossierDraft,
     ) {
         let mut partial = PartialAnswers::default();
         for field in crate::dossier_conversation::protocol::BRIEF_FIELDS {
             let val = crate::dossier::answer(&draft.answers, field);
             if !val.trim().is_empty() {
