display.text:
//! Managed local LiteRT-LM server lifecycle and child-process state machine.
//!
//! Authoritative reference: `desktop/litert-server.ts` and `desktop/main.ts`.
//!
//! When enabled via `TWYNE_DESKTOP_LOCAL_AI=true`, this manages the bundled
//! OpenBMB MiniCPM5 LiteRT-LM binary, imports the model if not already registered,
//! and starts the OpenAI-compatible loopback server on a free loopback port.
//!
//! Features:
//! - Bounded child-process execution and readiness probing (TCP connection attempts).
//! - Clean termination (SIGTERM / kill) on shutdown or drop to prevent orphan background servers.
//! - Non-blocking status inspections and health checks.
//! - Testable overrides for paths, timeouts, and poll intervals without modifying system environment.

use std::{
    env,
    io::{self, Read},
    net::{TcpListener, TcpStream},
    path::{Path, PathBuf},
    process::{Child, Command, Stdio},
    sync::{
        Arc, Mutex,
        atomic::{AtomicBool, Ordering},
    },
    thread,
    time::{Duration, Instant, SystemTime, UNIX_EPOCH},
};

pub const LOCAL_MODEL_ID: &str = "minicpm5-2b";
pub const LOCAL_PROVIDER_ID: &str = "desktop-litert-local";
pub const DEFAULT_LOOPBACK_HOST: &str = "127.0.0.1";
pub const DEFAULT_STARTUP_TIMEOUT_MS: u64 = 20_000;
pub const DEFAULT_STARTUP_POLL_MS: u64 = 150;
pub const DEFAULT_BIN_PATH: &str = "./bin/litert-lm";
pub const DEFAULT_MODEL_PATH: &str = "./models/MiniCPM5-2B_int4.litertlm";
const MAX_REGISTRY_OUTPUT_BYTES: usize = 256 * 1024;

#[derive(Debug)]
pub enum LiteRtError {
    Disabled,
    MissingAssets {
        bin_exists: bool,
        model_exists: bool,
        bin_path: PathBuf,
        model_path: PathBuf,
    },
    Io(io::Error),
    RegistryCheckFailed(String),
    ImportFailed(String),
    StartupFailed(String),
}

impl std::fmt::Display for LiteRtError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            Self::Disabled => write!(f, "Local LiteRT is disabled"),
            Self::MissingAssets { bin_path, model_path, .. } => {
                write!(
                    f,
                    "LiteRT assets missing: bin={}, model={}",
                    bin_path.display(),
                    model_path.display()
                )
            }
            Self::Io(err) => write!(f, "LiteRT I/O error: {err}"),
            Self::RegistryCheckFailed(msg) => write!(f, "LiteRT registry check failed: {msg}"),
            Self::ImportFailed(msg) => write!(f, "LiteRT model import failed: {msg}"),
            Self::StartupFailed(msg) => write!(f, "LiteRT server startup failed: {msg}"),
        }
    }
}

impl std::error::Error for LiteRtError {}

impl From<io::Error> for LiteRtError {
    fn from(err: io::Error) -> Self {
        Self::Io(err)
    }
}

/// Lifecycle state machine for the local LiteRT-LM server.
#[derive(Clone, Debug, PartialEq, Eq)]
pub enum LiteRtState {
    /// Local AI is disabled (`TWYNE_DESKTOP_LOCAL_AI` is not true/1).
    Disabled,
    /// Local AI is enabled but either the binary or model asset is missing.
    MissingAssets {
        bin_exists: bool,
        model_exists: bool,
        bin_path: PathBuf,
        model_path: PathBuf,
    },
    /// Checking LiteRT-LM registry for the model ID.
    CheckingRegistry,
    /// Importing the bundled model into LiteRT-LM registry.
    ImportingModel {
        model_id: String,
    },
    /// Spawning the server and waiting for port readiness.
    Starting {
        port: u16,
        pid: u32,
        started_at_ms: u64,
    },
    /// Server is up, port is accepting connections, and OpenAI-compatible endpoint is ready.
    Ready {
        port: u16,
        pid: u32,
        base_url: String,
    },
    /// Server failed to start, timed out, or exited with an error.
    Failed {
        stage: String,
        reason: String,
        timestamp_ms: u64,
    },
    /// Server was stopped gracefully.
    Stopped,
}

impl LiteRtState {
    pub fn is_ready(&self) -> bool {
        matches!(self, Self::Ready { .. })
    }

    pub fn port(&self) -> Option<u16> {
        match self {
            Self::Starting { port, .. } | Self::Ready { port, .. } => Some(*port),
            _ => None,
        }
    }

    pub fn base_url(&self) -> Option<&str> {
        match self {
            Self::Ready { base_url, .. } => Some(base_url.as_str()),
            _ => None,
        }
    }
}

/// Configuration for the LiteRT server lifecycle.
#[derive(Clone, Debug)]
pub struct LiteRtConfig {
    pub enabled: bool,
    pub bin_path: PathBuf,
    pub model_path: PathBuf,
    pub model_id: String,
    pub host: String,
    pub startup_timeout: Duration,
    pub startup_poll_interval: Duration,
}

impl Default for LiteRtConfig {
    fn default() -> Self {
        Self::from_env()
    }
}

impl LiteRtConfig {
    /// Load configuration from environment variables, matching `desktop/litert-server.ts`.
    pub fn from_env() -> Self {
        let enabled_raw = env::var("TWYNE_DESKTOP_LOCAL_AI").unwrap_or_default();
        let enabled = enabled_raw == "true" || enabled_raw == "1";

        let bin_path = PathBuf::from(
            env::var("LITERT_LM_BIN").unwrap_or_else(|_| DEFAULT_BIN_PATH.to_string()),
        );
        let model_path = PathBuf::from(
            env::var("LOCAL_MODEL_PATH").unwrap_or_else(|_| DEFAULT_MODEL_PATH.to_string()),
        );

        let timeout_ms = env::var("LITERT_LM_STARTUP_TIMEOUT_MS")
            .or_else(|_| env::var("LITERT_SERVER_STARTUP_TIMEOUT_MS"))
            .ok()
            .and_then(|v| v.parse::<u64>().ok())
            .unwrap_or(DEFAULT_STARTUP_TIMEOUT_MS);

        Self {
            enabled,
            bin_path,
            model_path,
            model_id: LOCAL_MODEL_ID.to_string(),
            host: DEFAULT_LOOPBACK_HOST.to_string(),
            startup_timeout: Duration::from_millis(timeout_ms),
            startup_poll_interval: Duration::from_millis(DEFAULT_STARTUP_POLL_MS),
        }
    }
}

/// Find a free TCP port on loopback.
pub fn allocate_free_port(host: &str) -> io::Result<u16> {
    let listener = TcpListener::bind(format!("{host}:0"))?;
    let port = listener.local_addr()?.port();
    drop(listener);
    Ok(port)
}

/// Test whether a loopback port is currently accepting TCP connections.
pub fn is_port_accepting_connections(host: &str, port: u16, timeout: Duration) -> bool {
    let addr = format!("{host}:{port}");
    TcpStream::connect_timeout(
        &addr.parse().unwrap_or_else(|_| "127.0.0.1:0".parse().unwrap()),
        timeout,
    )
    .is_ok()
}

/// Check whether the local model is already registered in LiteRT-LM registry.
/// Runs `litert-lm list` and checks output whitespace tokens.
pub fn model_is_registered(bin: &Path, model_id: &str) -> Result<bool, LiteRtError> {
    let mut child = Command::new(bin)
        .arg("list")
        .stdout(Stdio::piped())
        .stderr(Stdio::null())
        .spawn()
        .map_err(|e| LiteRtError::RegistryCheckFailed(format!("Failed to spawn {} list: {e}", bin.display())))?;

    let mut stdout = child
        .stdout
        .take()
        .ok_or_else(|| LiteRtError::RegistryCheckFailed("Failed to open child stdout pipe".into()))?;

    let mut buffer = Vec::new();
    let mut chunk = [0u8; 4096];
    while buffer.len() < MAX_REGISTRY_OUTPUT_BYTES {
        let n = stdout.read(&mut chunk)?;
        if n == 0 {
            break;
        }
        buffer.extend_from_slice(&chunk[..n]);
    }

    let status = child.wait()?;
    if !status.success() {
        return Ok(false);
    }

    let output_str = String::from_utf8_lossy(&buffer);
    let registered = output_str
        .split_whitespace()
        .any(|token| token == model_id);
    Ok(registered)
}

/// Import the bundled model into LiteRT-LM registry under `model_id`.
pub fn import_model(bin: &Path, model_path: &Path, model_id: &str) -> Result<(), LiteRtError> {
    if model_is_registered(bin, model_id)? {
        return Ok(());
    }

    let model_str = model_path
        .to_str()
        .ok_or_else(|| LiteRtError::ImportFailed("Invalid UTF-8 model path".into()))?;

    let status = Command::new(bin)
        .args(["import", model_str, model_id])
        .stdout(Stdio::inherit())
        .stderr(Stdio::inherit())
        .status()
        .map_err(|e| LiteRtError::ImportFailed(format!("Failed to execute {} import: {e}", bin.display())))?;

    if !status.success() {
        return Err(LiteRtError::ImportFailed(format!("LiteRT model import exited with status {status}")));
    }
    Ok(())
}

/// Handle to the live LiteRT child server process.
/// Guarantees process termination on Drop or explicit `stop()`.
pub struct LiteRtServerHandle {
    pub port: u16,
    pub pid: u32,
    pub base_url: String,
    child: Arc<Mutex<Option<Child>>>,
    stopped: Arc<AtomicBool>,
}

impl LiteRtServerHandle {
    pub fn new(port: u16, pid: u32, base_url: String, child: Child) -> Self {
        Self {
            port,
            pid,
            base_url,
            child: Arc::new(Mutex::new(Some(child))),
            stopped: Arc::new(AtomicBool::new(false)),
        }
    }

    /// Check if the child process is still running.
    pub fn is_alive(&self) -> bool {
        if self.stopped.load(Ordering::SeqCst) {
            return false;
        }
        let mut guard = self.child.lock().unwrap();
        if let Some(ref mut child) = *guard {
            match child.try_wait() {
                Ok(None) => true,
                _ => false,
            }
        } else {
            false
        }
    }

    /// Stop the server process gracefully, falling back to kill if needed.
    pub fn stop(&self) {
        if self.stopped.swap(true, Ordering::SeqCst) {
            return;
        }
        let mut guard = self.child.lock().unwrap();
        if let Some(mut child) = guard.take() {
            let _ = child.kill();
            let _ = child.wait();
        }
    }
}

impl Drop for LiteRtServerHandle {
    fn drop(&mut self) {
        self.stop();
    }
}

/// Bounded startup readiness state machine.
pub fn wait_for_server_ready(
    child: &mut Child,
    host: &str,
    port: u16,
    timeout: Duration,
    poll_interval: Duration,
) -> Result<(), String> {
    let deadline = Instant::now() + timeout;

    while Instant::now() < deadline {
        // 1. Check if port is open and accepting TCP connections
        if is_port_accepting_connections(host, port, Duration::from_millis(50)) {
            return Ok(());
        }

        // 2. Check if child process exited prematurely
        match child.try_wait() {
            Ok(Some(status)) => {
                return Err(format!("Server process exited before ready with status: {status}"));
            }
            Ok(None) => {
                // Still running, sleep for poll interval
                thread::sleep(poll_interval);
            }
            Err(err) => {
                return Err(format!("Error polling server process: {err}"));
            }
        }
    }

    Err(format!("Server timed out after {}ms waiting for loopback port {port}", timeout.as_millis()))
}

fn current_time_ms() -> u64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default()
        .as_millis() as u64
}

/// High-level manager coordinating configuration, startup checks, port allocation,
/// child lifecycle, and shutdown.
pub struct LiteRtProcessManager {
    config: LiteRtConfig,
    state: LiteRtState,
    handle: Option<Arc<LiteRtServerHandle>>,
}

impl LiteRtProcessManager {
    pub fn new(config: LiteRtConfig) -> Self {
        let state = if config.enabled {
            LiteRtState::Stopped
        } else {
            LiteRtState::Disabled
        };
        Self {
            config,
            state,
            handle: None,
        }
    }

    pub fn state(&self) -> &LiteRtState {
        &self.state
    }

    pub fn config(&self) -> &LiteRtConfig {
        &self.config
    }

    pub fn is_ready(&self) -> bool {
        self.state.is_ready() && self.handle.as_ref().map_or(false, |h| h.is_alive())
    }

    pub fn base_url(&self) -> Option<&str> {
        self.state.base_url()
    }

    pub fn port(&self) -> Option<u16> {
        self.state.port()
    }

    /// Check if the running server is still alive. If it exited unexpectedly,
    /// transition state to `Failed`.
    pub fn poll_health(&mut self) -> &LiteRtState {
        if let LiteRtState::Ready { port, pid, .. } = self.state {
            let alive = self.handle.as_ref().map_or(false, |h| h.is_alive());
            if !alive {
                self.state = LiteRtState::Failed {
                    stage: "runtime".to_string(),
                    reason: format!("Server process (pid {pid}, port {port}) died unexpectedly"),
                    timestamp_ms: current_time_ms(),
                };
                self.handle = None;
            }
        }
        &self.state
    }

    /// Start the local AI server following the authoritative Source protocol:
    /// 1. Check if enabled.
    /// 2. Validate asset files exist on disk.
    /// 3. Allocate free loopback port.
    /// 4. Verify/import model into LiteRT registry.
    /// 5. Spawn `litert-lm serve --host 127.0.0.1 --port <port>`.
    /// 6. Bounded poll for connection readiness.
    pub fn start(&mut self) -> Result<Option<String>, LiteRtError> {
        if !self.config.enabled {
            self.state = LiteRtState::Disabled;
            return Ok(None);
        }

        let bin_exists = self.config.bin_path.exists();
        let model_exists = self.config.model_path.exists();

        if !bin_exists || !model_exists {
            let state = LiteRtState::MissingAssets {
                bin_exists,
                model_exists,
                bin_path: self.config.bin_path.clone(),
                model_path: self.config.model_path.clone(),
            };
            self.state = state;
            return Ok(None);
        }

        let port = allocate_free_port(&self.config.host)
            .map_err(LiteRtError::Io)?;

        self.state = LiteRtState::CheckingRegistry;
        if let Err(err) = import_model(&self.config.bin_path, &self.config.model_path, &self.config.model_id) {
            let msg = err.to_string();
            self.state = LiteRtState::Failed {
                stage: "import".to_string(),
                reason: msg,
                timestamp_ms: current_time_ms(),
            };
            return Err(err);
        }

        let mut child = Command::new(&self.config.bin_path)
            .args(["serve", "--host", &self.config.host, "--port", &port.to_string()])
            .stdout(Stdio::inherit())
            .stderr(Stdio::inherit())
            .spawn()
            .map_err(|e| LiteRtError::StartupFailed(format!("Failed to spawn local server: {e}")))?;

        let pid = child.id();
        self.state = LiteRtState::Starting {
            port,
            pid,
            started_at_ms: current_time_ms(),
        };

        if let Err(reason) = wait_for_server_ready(
            &mut child,
            &self.config.host,
            port,
            self.config.startup_timeout,
            self.config.startup_poll_interval,
        ) {
            let _ = child.kill();
            let _ = child.wait();
            self.state = LiteRtState::Failed {
                stage: "readiness".to_string(),
                reason: reason.clone(),
                timestamp_ms: current_time_ms(),
            };
            return Err(LiteRtError::StartupFailed(reason));
        }

        let base_url = format!("http://{}:{port}/v1", self.config.host);
        let handle = LiteRtServerHandle::new(port, pid, base_url.clone(), child);
        self.handle = Some(Arc::new(handle));
        self.state = LiteRtState::Ready {
            port,
            pid,
            base_url: base_url.clone(),
        };

        Ok(Some(base_url))
    }

    /// Stop the server process cleanly.
    pub fn stop(&mut self) {
        if let Some(handle) = self.handle.take() {
            handle.stop();
        }
        self.state = LiteRtState::Stopped;
    }
}

impl Drop for LiteRtProcessManager {
    fn drop(&mut self) {
        self.stop();
    }
}

