//! Zero-dependency native loopback HTTP/1.1 and SSE client for local OpenAI-compatible servers.
//!
//! Connects to `http://127.0.0.1:<port>/v1/chat/completions` using `std::net::TcpStream`.
//! Implements bounded chunk reading, Server-Sent Events parsing, cancellation checking,
//! and accurate error classification.
//!
//! Includes a testable in-process `MockLoopbackServer` for unit verification of connection,
//! streaming, timeout, and cancellation behavior.

use super::{
    request::{CancellationToken, CompletionRequest, MAX_RESPONSE_BYTES},
    stream_accumulator::{
        GenerationStreamAccumulator, GenerationStreamInput, GenerationStreamSnapshot,
    },
};
use serde_json::{Value, json};
use std::{
    io::{self, BufRead, BufReader, Read, Write},
