display.text:
//! Zero-dependency native loopback HTTP/1.1 and SSE client for local OpenAI-compatible servers.
//!
//! Connects to `http://127.0.0.1:<port>/v1/chat/completions` using `std::net::TcpStream`.
//! Implements bounded chunk reading, Server-Sent Events parsing, cancellation checking,
//! and accurate error classification.
//!
//! Includes a testable in-process `MockLoopbackServer` for unit verification of connection,
//! streaming, timeout, and cancellation behavior.

use super::{
    request::{CancellationToken, CompletionRequest, MAX_RESPONSE_BYTES},
    stream_accumulator::{
        GenerationStreamAccumulator, GenerationStreamInput, GenerationStreamSnapshot,
    },
};
use serde_json::{Value, json};
use std::{
    io::{self, BufRead, BufReader, Read, Write},
    net::{TcpListener, TcpStream},
    sync::{
        Arc,
        atomic::{AtomicBool, Ordering},
    },
    thread,
    time::{Duration, Instant},
};

const MAX_SSE_LINE_BYTES: usize = 64 * 1024; // 64 KiB line limit

#[derive(Clone, Debug, PartialEq, Eq)]
pub enum AiError {
    ConnectionRefused(String),
    Timeout(String),
    HttpError { status: u16, message: String },
    Cancelled,
    MalformedResponse(String),
    PayloadTooLarge(usize),
}

impl std::fmt::Display for AiError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            Self::ConnectionRefused(msg) => write!(f, "Connection refused: {msg}"),
            Self::Timeout(msg) => write!(f, "Request timed out: {msg}"),
            Self::HttpError { status, message } => write!(f, "HTTP {status}: {message}"),
            Self::Cancelled => write!(f, "Request was cancelled"),
            Self::MalformedResponse(msg) => write!(f, "Malformed provider response: {msg}"),
            Self::PayloadTooLarge(sz) => write!(f, "Response exceeded byte limit ({sz} bytes)"),
        }
    }
}

impl std::error::Error for AiError {}

/// Completion result returned after request completes.
#[derive(Clone, Debug, PartialEq)]
pub struct CompletionResult {
    pub text: String,
    pub reasoning: String,
    pub snapshot: GenerationStreamSnapshot,
    pub raw_json: Option<Value>,
}

/// Loopback HTTP/1.1 transport client.
pub struct LoopbackClient {
    host: String,
    port: u16,
}

impl LoopbackClient {
    pub fn new(host: impl Into<String>, port: u16) -> Self {
        Self {
            host: host.into(),
            port,
        }
    }

    pub fn from_base_url(base_url: &str) -> Option<Self> {
        let trimmed = base_url.trim_start_matches("http://").trim_start_matches("https://");
        let (host_port, _) = trimmed.split_once('/').unwrap_or((trimmed, ""));
        let (host, port_str) = host_port.split_once(':')?;
        let port = port_str.parse::<u16>().ok()?;
        Some(Self::new(host, port))
    }

    /// Build OpenAI-compatible request payload JSON.
    pub fn build_payload(req: &CompletionRequest) -> String {
        let messages_json: Vec<Value> = req
            .messages
            .iter()
            .map(|m| json!({ "role": m.role, "content": m.content }))
            .collect();

        let mut payload = json!({
            "model": req.model,
            "messages": messages_json,
            "temperature": req.temperature,
            "stream": req.stream,
        });

        if let Some(tokens) = req.max_tokens {
            payload["max_tokens"] = json!(tokens);
        }

        payload.to_string()
    }

    /// Send a non-streaming completion request.
    pub fn send_completion(&self, req: &CompletionRequest) -> Result<CompletionResult, AiError> {
        let payload = Self::build_payload(req);
        let stream = self.connect_and_send("/v1/chat/completions", &payload, req.timeout, &req.cancel_token)?;

        let mut reader = BufReader::new(stream);
        let (status, headers) = parse_http_headers(&mut reader, req.timeout, &req.cancel_token)?;

        if status != 200 {
            let error_body = read_all_body(&mut reader, &headers, req.timeout)?;
            return Err(AiError::HttpError {
                status,
                message: error_body,
            });
        }

        let body = read_all_body(&mut reader, &headers, req.timeout)?;
        let val: Value = serde_json::from_str(&body)
            .map_err(|e| AiError::MalformedResponse(format!("Invalid JSON: {e}")))?;

        let text = val["choices"][0]["message"]["content"]
            .as_str()
            .unwrap_or_default()
            .to_string();

        let reasoning = val["choices"][0]["message"]["reasoning_content"]
            .as_str()
            .unwrap_or_default()
            .to_string();

        let snapshot = GenerationStreamSnapshot::completed(text.clone(), reasoning.clone());

        Ok(CompletionResult {
            text,
            reasoning,
            snapshot,
            raw_json: Some(val),
        })
    }

    /// Stream a completion request, calling `on_snapshot` on every delta.
    /// Halts if cancelled or if `on_snapshot` returns false.
    pub fn stream_completion<F>(
        &self,
        req: &CompletionRequest,
        mut on_snapshot: F,
    ) -> Result<CompletionResult, AiError>
    where
        F: FnMut(&GenerationStreamSnapshot) -> bool,
    {
        let mut stream_req = req.clone();
        stream_req.stream = true;
        let payload = Self::build_payload(&stream_req);

        let stream = self.connect_and_send("/v1/chat/completions", &payload, req.timeout, &req.cancel_token)?;
        let mut reader = BufReader::new(stream);
        let (status, _) = parse_http_headers(&mut reader, req.timeout, &req.cancel_token)?;

        if status != 200 {
            let mut line = String::new();
            let _ = reader.read_line(&mut line);
            return Err(AiError::HttpError {
                status,
                message: line.trim().to_string(),
            });
        }

        let mut accumulator = GenerationStreamAccumulator::new();
        let mut total_bytes = 0;
        let mut line_buf = String::new();
        let deadline = Instant::now() + req.timeout;

        while Instant::now() < deadline {
            if req.cancel_token.is_cancelled() {
                return Err(AiError::Cancelled);
            }

            line_buf.clear();
            let n = reader
                .read_line(&mut line_buf)
                .map_err(|e| AiError::Timeout(format!("Stream read error: {e}")))?;

            if n > MAX_SSE_LINE_BYTES {
                return Err(AiError::PayloadTooLarge(n));
            }

            if n == 0 {
                // EOF reached
                break;
            }

            total_bytes += n;
            if total_bytes > MAX_RESPONSE_BYTES {
                return Err(AiError::PayloadTooLarge(total_bytes));
            }

            let trimmed = line_buf.trim();
            if trimmed.is_empty() || trimmed.starts_with(':') {
                // Empty heartbeat line or comment
                continue;
            }

            if let Some(data) = trimmed.strip_prefix("data:") {
                let data_trimmed = data.trim();
                if data_trimmed == "[DONE]" {
                    accumulator.push(GenerationStreamInput::Finish);
                    break;
                }

                if let Ok(chunk_val) = serde_json::from_str::<Value>(data_trimmed) {
                    if let Some(choice) = chunk_val["choices"].get(0) {
                        let delta = &choice["delta"];
                        if let Some(content) = delta["content"].as_str() {
                            accumulator.push(GenerationStreamInput::TextDelta(content.to_string()));
                        }
                        if let Some(reasoning) = delta["reasoning_content"].as_str() {
                            accumulator.push(GenerationStreamInput::ReasoningDelta(reasoning.to_string()));
                        }
                    }
                }

                let current_snap = accumulator.snapshot();
                let should_continue = on_snapshot(&current_snap);
                if !should_continue {
                    req.cancel_token.cancel();
                    return Err(AiError::Cancelled);
                }
            }
        }

        if Instant::now() >= deadline {
            return Err(AiError::Timeout(format!("Stream timed out after {}ms", req.timeout.as_millis())));
        }

        let final_snapshot = accumulator.push(GenerationStreamInput::Finish);
        Ok(CompletionResult {
            text: final_snapshot.text.clone(),
            reasoning: final_snapshot.reasoning.clone(),
            snapshot: final_snapshot,
            raw_json: None,
        })
    }

    fn connect_and_send(
        &self,
        path: &str,
        payload: &str,
        timeout: Duration,
        cancel_token: &CancellationToken,
    ) -> Result<TcpStream, AiError> {
        if cancel_token.is_cancelled() {
            return Err(AiError::Cancelled);
        }

        let addr_str = format!("{}:{}", self.host, self.port);
        let addr = addr_str
            .parse()
            .map_err(|e| AiError::ConnectionRefused(format!("Invalid loopback address: {e}")))?;

        let mut stream = TcpStream::connect_timeout(&addr, timeout)
            .map_err(|e| AiError::ConnectionRefused(format!("Failed to connect to loopback {addr_str}: {e}")))?;

        stream
            .set_read_timeout(Some(timeout))
            .map_err(|e| AiError::ConnectionRefused(format!("Failed to set read timeout: {e}")))?;
        stream
            .set_write_timeout(Some(timeout))
            .map_err(|e| AiError::ConnectionRefused(format!("Failed to set write timeout: {e}")))?;

        let http_request = format!(
            "POST {path} HTTP/1.1\r\n\
             Host: {}:{}\r\n\
             Content-Type: application/json\r\n\
             Accept: text/event-stream, application/json\r\n\
             Content-Length: {}\r\n\
             Connection: close\r\n\
             \r\n\
             {}",
            self.host,
            self.port,
            payload.len(),
            payload
        );

        stream
            .write_all(http_request.as_bytes())
            .map_err(|e| AiError::Timeout(format!("Failed to write HTTP request: {e}")))?;

        Ok(stream)
    }
}

// ── HTTP Parsing Helpers ──

fn parse_http_headers(
    reader: &mut BufReader<TcpStream>,
    _timeout: Duration,
    cancel_token: &CancellationToken,
) -> Result<(u16, Vec<(String, String)>), AiError> {
    let mut status_line = String::new();
    reader
        .read_line(&mut status_line)
        .map_err(|e| AiError::Timeout(format!("Failed to read HTTP status line: {e}")))?;

    if cancel_token.is_cancelled() {
        return Err(AiError::Cancelled);
    }

    let status_parts: Vec<&str> = status_line.split_whitespace().collect();
    if status_parts.len() < 2 {
        return Err(AiError::MalformedResponse(format!("Malformed status line: {status_line}")));
    }

    let status_code: u16 = status_parts[1]
        .parse()
        .map_err(|_| AiError::MalformedResponse(format!("Invalid status code: {}", status_parts[1])))?;

    let mut headers = Vec::new();
    let mut line = String::new();

    loop {
        line.clear();
        reader
            .read_line(&mut line)
            .map_err(|e| AiError::Timeout(format!("Failed reading headers: {e}")))?;

        let trimmed = line.trim();
        if trimmed.is_empty() {
            break;
        }

        if let Some((k, v)) = trimmed.split_once(':') {
            headers.push((k.trim().to_ascii_lowercase(), v.trim().to_string()));
        }
    }

    Ok((status_code, headers))
}

fn read_all_body(
    reader: &mut BufReader<TcpStream>,
    headers: &[(String, String)],
    _timeout: Duration,
) -> Result<String, AiError> {
    let content_length = headers
        .iter()
        .find(|(k, _)| k == "content-length")
        .and_then(|(_, v)| v.parse::<usize>().ok());

    let mut body = String::new();
    if let Some(len) = content_length {
        if len > MAX_RESPONSE_BYTES {
            return Err(AiError::PayloadTooLarge(len));
        }
        let mut buf = vec![0u8; len];
        reader
            .read_exact(&mut buf)
            .map_err(|e| AiError::Timeout(format!("Failed to read {len} bytes: {e}")))?;
        body = String::from_utf8_lossy(&buf).to_string();
    } else {
        reader
            .read_to_string(&mut body)
            .map_err(|e| AiError::Timeout(format!("Failed reading body: {e}")))?;
    }

    Ok(body)
}

// ── Synthetic Test Mock Server ──

/// In-process mock loopback server for deterministically testing client behavior.
pub struct MockLoopbackServer {
    #[allow(dead_code)]
    listener: TcpListener,
    port: u16,
    shutdown: Arc<AtomicBool>,
}

#[derive(Clone, Debug)]
pub enum MockServerResponse {
    DirectJson(String),
    StreamSse(Vec<String>),
    ErrorStatus(u16, String),
    DelayedStream(Vec<String>, Duration),
}

impl MockLoopbackServer {
    pub fn spawn(response: MockServerResponse) -> io::Result<Self> {
        let listener = TcpListener::bind("127.0.0.1:0")?;
        let port = listener.local_addr()?.port();
        let shutdown = Arc::new(AtomicBool::new(false));
        let shutdown_clone = Arc::clone(&shutdown);

        let listener_clone = listener.try_clone()?;
        thread::spawn(move || {
            let _ = listener_clone.set_nonblocking(true);
            while !shutdown_clone.load(Ordering::SeqCst) {
                match listener_clone.accept() {
                    Ok((mut stream, _)) => {
                        let _ = handle_mock_client(&mut stream, &response);
                    }
                    Err(ref e) if e.kind() == io::ErrorKind::WouldBlock => {
                        thread::sleep(Duration::from_millis(10));
                    }
                    Err(_) => break,
                }
            }
        });

        Ok(Self {
            listener,
            port,
            shutdown,
        })
    }

    pub fn port(&self) -> u16 {
        self.port
    }

    pub fn base_url(&self) -> String {
        format!("http://127.0.0.1:{}/v1", self.port)
    }

    pub fn stop(&self) {
        self.shutdown.store(true, Ordering::SeqCst);
    }
}

impl Drop for MockLoopbackServer {
    fn drop(&mut self) {
        self.stop();
    }
}

fn handle_mock_client(stream: &mut TcpStream, response: &MockServerResponse) -> io::Result<()> {
    let mut reader = BufReader::new(stream.try_clone()?);
    let mut line = String::new();

    // Read headers until empty line
    while reader.read_line(&mut line)? > 0 {
        if line.trim().is_empty() {
            break;
        }
        line.clear();
    }

    match response {
        MockServerResponse::DirectJson(json_str) => {
            let resp = format!(
                "HTTP/1.1 200 OK\r\n\
                 Content-Type: application/json\r\n\
                 Content-Length: {}\r\n\
                 Connection: close\r\n\
                 \r\n\
                 {}",
                json_str.len(),
                json_str
            );
            stream.write_all(resp.as_bytes())?;
        }
        MockServerResponse::StreamSse(chunks) => {
            let headers = "HTTP/1.1 200 OK\r\n\
                           Content-Type: text/event-stream\r\n\
                           Connection: close\r\n\
                           \r\n";
            stream.write_all(headers.as_bytes())?;
            for chunk in chunks {
                let sse_line = format!("data: {chunk}\r\n\r\n");
                stream.write_all(sse_line.as_bytes())?;
                stream.flush()?;
            }
            stream.write_all(b"data: [DONE]\r\n\r\n")?;
        }
        MockServerResponse::DelayedStream(chunks, delay) => {
            let headers = "HTTP/1.1 200 OK\r\n\
                           Content-Type: text/event-stream\r\n\
                           Connection: close\r\n\
                           \r\n";
            stream.write_all(headers.as_bytes())?;
            for chunk in chunks {
                thread::sleep(*delay);
                let sse_line = format!("data: {chunk}\r\n\r\n");
                if stream.write_all(sse_line.as_bytes()).is_err() {
                    break;
                }
                let _ = stream.flush();
            }
            let _ = stream.write_all(b"data: [DONE]\r\n\r\n");
        }
        MockServerResponse::ErrorStatus(code, msg) => {
            let resp = format!(
                "HTTP/1.1 {code} Error\r\n\
                 Content-Type: text/plain\r\n\
                 Content-Length: {}\r\n\
                 Connection: close\r\n\
                 \r\n\
                 {}",
                msg.len(),
                msg
            );
            stream.write_all(resp.as_bytes())?;
        }
    }

    Ok(())
}

