//! Structured output parsing for Rubric judges, research target extraction, and interview tags.
//!
//! Authoritative sources:
//! - `src/utils/llm-parsing.ts`
//! - `src/utils/research-targets.ts`
//! - `src/utils/reasoning-tags.ts`

use super::stream_accumulator::strip_reasoning_tags;
use serde::{Deserialize, Serialize};
use serde_json::Value;

/// Clamped 1..=10 score and rationale from Rubric evaluation judges.
#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
pub struct JudgeOutput {
    pub score: u8,
    pub rationale: String,
}

pub fn clamp_score(score: f64) -> u8 {
    if !score.is_finite() {
        return 5;
    }
    let rounded = score.round() as i64;
    rounded.clamp(1, 10) as u8
}

/// Strip Markdown code fences (` ```json ` or ` ``` `).
pub fn strip_json_fences(text: &str) -> String {
    let mut out = String::new();
    let mut in_fence = false;
    for line in text.lines() {
        let trimmed = line.trim();
        if trimmed.starts_with("```") {
            in_fence = !in_fence;
            continue;
        }
        out.push_str(line);
        out.push('\n');
    }
    out.trim().to_string()
}

/// Locate and extract the first balanced `{ ... }` JSON object.
pub fn extract_first_json_object(text: &str) -> Option<String> {
    let open = text.find('{')?;
    let mut depth = 0;
    let mut in_string = false;
    let mut escaped = false;

    for (i, ch) in text[open..].char_indices() {
        if escaped {
            escaped = false;
            continue;
        }
        if ch == '\\' && in_string {
            escaped = true;
            continue;
        }
        if ch == '"' {
            in_string = !in_string;
            continue;
        }
        if in_string {
            continue;
        }

        if ch == '{' {
            depth += 1;
        } else if ch == '}' {
            depth -= 1;
            if depth == 0 {
                let end = open + i;
                return Some(text[open..=end].to_string());
            }
        }
    }

    None
}

/// Tagged JSON segment (e.g., DOSSIER: { ... }, SYNTHESIZE: { ... }, PROBE: { ... }).
#[derive(Clone, Debug, PartialEq)]
pub struct TaggedJsonSegment {
    pub tag: String,
    pub value: Value,
    pub start: usize,
    pub end: usize,
}

/// Extract tagged JSON block matching `tag: { ... }`.
pub fn extract_tagged_json(text: &str, tag: &str) -> Option<TaggedJsonSegment> {
    let lower_text = text.to_ascii_lowercase();
    let marker = format!("{}:", tag.to_ascii_lowercase());
    let marker_idx = lower_text.find(&marker)?;

    let search_start = marker_idx + marker.len();
    let open_rel = text[search_start..].find('{')?;
    let open = search_start + open_rel;

    let mut depth = 0;
    let mut in_string = false;
    let mut escaped = false;

    for (i, ch) in text[open..].char_indices() {
        if escaped {
            escaped = false;
            continue;
        }
        if ch == '\\' && in_string {
            escaped = true;
            continue;
        }
        if ch == '"' {
            in_string = !in_string;
            continue;
        }
        if in_string {
            continue;
        }

        if ch == '{' {
            depth += 1;
        } else if ch == '}' {
            depth -= 1;
            if depth == 0 {
                let end = open + i + 1;
                let json_slice = &text[open..end];
                if let Ok(value) = serde_json::from_str::<Value>(json_slice) {
                    return Some(TaggedJsonSegment {
                        tag: tag.to_string(),
                        value,
                        start: marker_idx,
                        end,
                    });
                }
            }
        }
    }

    None
}

/// Parse Rubric judge output, supporting both structured JSON and regex fallbacks.
/// Matches `parseJudgeOutput` in `src/utils/llm-parsing.ts`.
pub fn parse_judge_output(text: &str) -> Option<JudgeOutput> {
    let stripped = strip_json_fences(&strip_reasoning_tags(text));
    let candidate = extract_first_json_object(&stripped).unwrap_or_else(|| stripped.clone());

    if let Ok(val) = serde_json::from_str::<Value>(&candidate) {
        if let Some(obj) = val.as_object() {
            let score_val = obj.get("score").and_then(|v| v.as_f64());
            let rationale_val = obj.get("rationale").and_then(|v| v.as_str());

            if let (Some(s), Some(r)) = (score_val, rationale_val) {
                return Some(JudgeOutput {
                    score: clamp_score(s),
                    rationale: r.to_string(),
                });
            }
        }
    }

    // Looser regex fallback matching source implementation
    let score_opt = candidate
        .lines()
        .find_map(|line| {
            let lower = line.to_ascii_lowercase();
            if lower.contains("score") {
                lower
                    .split(|c: char| !c.is_ascii_digit())
                    .find_map(|chunk| chunk.parse::<f64>().ok())
            } else {
                None
            }
        });

    let rationale_opt = candidate
        .lines()
        .find_map(|line| {
            let trimmed = line.trim();
            if trimmed.to_ascii_lowercase().starts_with("\"rationale\"")
                || trimmed.to_ascii_lowercase().starts_with("rationale:")
            {
                Some(
                    trimmed
                        .trim_start_matches(|c: char| c != ':')
                        .trim_start_matches(':')
                        .trim()
                        .trim_matches('"')
                        .to_string(),
                )
            } else {
                None
            }
        });

    if let Some(s) = score_opt {
        return Some(JudgeOutput {
            score: clamp_score(s),
            rationale: rationale_opt.unwrap_or_else(|| {
                "The draft does part of the work and leaves the rest to the writer.".to_string()
            }),
        });
    }

    None
}

