#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "lowercase")]
pub enum ResearchTargetKind {
    Quote,
    Work,
    Person,
    Statistic,
    Claim,
    Event,
}

#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
pub struct ResearchTarget {
    pub kind: ResearchTargetKind,
    pub anchor: String,
    pub query: String,
}

/// Parse array of ResearchTargets from model response text.
/// Extracts JSON array whether bare or wrapped in markdown code blocks.
pub fn parse_research_targets(text: &str, max_targets: usize) -> Result<Vec<ResearchTarget>, String> {
    let stripped = strip_json_fences(&strip_reasoning_tags(text));

    // Try finding array `[ ... ]`
    let array_str = if let (Some(open), Some(close)) = (stripped.find('['), stripped.rfind(']')) {
        if open < close {
            &stripped[open..=close]
        } else {
            &stripped
        }
    } else {
        &stripped
    };

    let parsed: Value = serde_json::from_str(array_str)
        .map_err(|e| format!("Failed to parse JSON array of targets: {e}"))?;

    let items = parsed
        .as_array()
        .ok_or_else(|| "Parsed research targets root is not an array".to_string())?;

    let mut targets = Vec::new();
    for item in items.iter().take(max_targets) {
        let kind_str = item.get("kind").and_then(Value::as_str).unwrap_or("claim");
        let kind = match kind_str.to_ascii_lowercase().as_str() {
            "quote" => ResearchTargetKind::Quote,
            "work" => ResearchTargetKind::Work,
            "person" => ResearchTargetKind::Person,
            "statistic" => ResearchTargetKind::Statistic,
            "event" => ResearchTargetKind::Event,
            _ => ResearchTargetKind::Claim,
        };

        let anchor = item.get("anchor").and_then(Value::as_str).unwrap_or_default().trim();
        let query = item.get("query").and_then(Value::as_str).unwrap_or_default().trim();

        if !anchor.is_empty() && !query.is_empty() {
            targets.push(ResearchTarget {
                kind,
                anchor: anchor.to_string(),
                query: query.to_string(),
            });
        }
    }

    Ok(targets)
}

