display.text:
//! Native AI coordinator integrating LiteRT lifecycle, transport, request routing,
//! in-flight cancellation, and manuscript revision validation.
//!
//! Enforces:
//! - Keeping whole-document analysis decoupled from keystrokes (revision guarding).
//! - Server-held credentials: API keys stay in the native backend, never exposed to views.
//! - Bounded concurrency and clean cancellation when switching folios.

use super::{
    litert_lifecycle::{
        LOCAL_PROVIDER_ID, LiteRtConfig, LiteRtError, LiteRtProcessManager, LiteRtState,
    },
    loopback_transport::{AiError, CompletionResult, LoopbackClient},
    provider_types::{
        AiFeature, AiProviderConfig, AiSettingsRecord, ResolvedFeatureConfig,
        resolve_feature_config, resolve_feature_config_for_persona,
    },
    request::{AiRequestId, CancellationToken, CompletionRequest, RevisionIdentity},
    stream_accumulator::GenerationStreamSnapshot,
};
use std::{
    collections::HashMap,
    sync::{Arc, Mutex},
    time::Instant,
};

#[allow(dead_code)]
#[derive(Clone, Debug)]
struct InFlightEntry {
    cancel_token: CancellationToken,
    folio_id: Option<String>,
    feature: AiFeature,
    started_at: Instant,
}

/// Central coordinator for native AI operations in the GPUI desktop shell.
pub struct NativeAiCoordinator {
    litert_manager: LiteRtProcessManager,
    settings: AiSettingsRecord,
    in_flight: Arc<Mutex<HashMap<AiRequestId, InFlightEntry>>>,
}

impl NativeAiCoordinator {
    pub fn new(litert_config: LiteRtConfig, settings: AiSettingsRecord) -> Self {
        Self {
            litert_manager: LiteRtProcessManager::new(litert_config),
            settings,
            in_flight: Arc::new(Mutex::new(HashMap::new())),
        }
    }

    /// Access the local LiteRT server manager.
    pub fn litert_manager(&self) -> &LiteRtProcessManager {
        &self.litert_manager
    }

    /// Mutable access to the local LiteRT server manager.
    pub fn litert_manager_mut(&mut self) -> &mut LiteRtProcessManager {
        &mut self.litert_manager
    }

    /// Current LiteRT server state.
    pub fn litert_state(&self) -> &LiteRtState {
        self.litert_manager.state()
    }

    /// True if the local model server is online and accepting connections.
    pub fn is_local_ai_ready(&self) -> bool {
        self.litert_manager.is_ready()
    }

    /// Start the local LiteRT server if enabled in configuration.
    pub fn start_local_ai(&mut self) -> Result<Option<String>, LiteRtError> {
        let res = self.litert_manager.start()?;
        if let Some(ref base_url) = res {
            // Auto-register the local provider in settings if not already present
            let local_id = LOCAL_PROVIDER_ID;
            if !self.settings.providers.iter().any(|p| p.id == local_id) {
                self.settings.providers.push(AiProviderConfig::new_litert(base_url.as_str()));
            }
        }
        Ok(res)
    }

    /// Stop the local LiteRT server.
    pub fn stop_local_ai(&mut self) {
        self.litert_manager.stop();
    }

    /// Update runtime AI settings.
    pub fn update_settings(&mut self, settings: AiSettingsRecord) {
        self.settings = settings;
    }

    pub fn settings(&self) -> &AiSettingsRecord {
        &self.settings
    }

    /// Resolve configuration for a feature, respecting settings and local LiteRT availability.
    pub fn resolve_feature(&self, feature: &AiFeature) -> Option<ResolvedFeatureConfig> {
        resolve_feature_config(&self.settings, feature)
    }

    /// Resolve configuration for a feature with persona-level overrides.
    pub fn resolve_feature_for_persona(
        &self,
        feature: &AiFeature,
        persona_provider_id: Option<&str>,
        persona_model: Option<&str>,
        persona_temperature: Option<f64>,
    ) -> Option<ResolvedFeatureConfig> {
        resolve_feature_config_for_persona(
            &self.settings,
            feature,
            persona_provider_id,
            persona_model,
            persona_temperature,
        )
    }

    /// Execute a non-streaming AI completion request through the local loopback transport.
    pub fn execute_request(&self, req: CompletionRequest) -> Result<CompletionResult, AiError> {
        let client = self.resolve_client(&req.provider_id)?;
        self.register_in_flight(&req);

        let res = client.send_completion(&req);
        self.unregister_in_flight(&req.request_id);

        res
    }

    /// Execute a streaming AI completion request, calling `on_snapshot` as tokens arrive.
    pub fn execute_streaming_request<F>(
        &self,
        req: CompletionRequest,
        on_snapshot: F,
    ) -> Result<CompletionResult, AiError>
    where
        F: FnMut(&GenerationStreamSnapshot) -> bool,
    {
        let client = self.resolve_client(&req.provider_id)?;
        self.register_in_flight(&req);

        let res = client.stream_completion(&req, on_snapshot);
        self.unregister_in_flight(&req.request_id);

        res
    }

    /// Cancel a specific inflight request by ID. Returns true if found and cancelled.
    pub fn cancel_request(&self, request_id: &AiRequestId) -> bool {
        let guard = self.in_flight.lock().unwrap();
        if let Some(entry) = guard.get(request_id) {
            entry.cancel_token.cancel();
            true
        } else {
            false
        }
    }

    /// Cancel all inflight requests associated with a folio (e.g. when writer closes or navigates).
    pub fn cancel_all_for_folio(&self, folio_id: &str) -> usize {
        let guard = self.in_flight.lock().unwrap();
        let mut count = 0;
        for entry in guard.values() {
            if entry.folio_id.as_deref() == Some(folio_id) {
                entry.cancel_token.cancel();
                count += 1;
            }
        }
        count
    }

    /// Verify whether a completed request's revision matches current manuscript generation.
    /// Prevents stale results from applying after user continues typing.
    pub fn is_revision_current(
        &self,
        expected: Option<&RevisionIdentity>,
        active_folio_id: &str,
        active_generation: u64,
    ) -> bool {
        match expected {
            Some(rev) => rev.is_current(active_folio_id, active_generation),
            None => true,
        }
    }

    fn resolve_client(&self, provider_id: &str) -> Result<LoopbackClient, AiError> {
        let provider = self
            .settings
            .providers
            .iter()
            .find(|p| p.id == provider_id)
            .ok_or_else(|| {
                AiError::ConnectionRefused(format!("Provider '{provider_id}' is not configured"))
            })?;

        let base_url = provider.base_url.as_deref().unwrap_or_default();
        LoopbackClient::from_base_url(base_url).ok_or_else(|| {
            AiError::ConnectionRefused(format!("Invalid loopback base URL for provider '{provider_id}': {base_url}"))
        })
    }

    fn register_in_flight(&self, req: &CompletionRequest) {
        let mut guard = self.in_flight.lock().unwrap();
        guard.insert(
            req.request_id.clone(),
            InFlightEntry {
                cancel_token: req.cancel_token.clone(),
                folio_id: req.revision.as_ref().map(|r| r.folio_id.clone()),
                feature: req.feature.clone(),
                started_at: Instant::now(),
            },
        );
    }

    fn unregister_in_flight(&self, id: &AiRequestId) {
        let mut guard = self.in_flight.lock().unwrap();
        guard.remove(id);
    }
}

