fn regex_score(text: &str) -> Option<f64> {
    let lower = text.to_ascii_lowercase();
    let mut search_from = 0;
    while let Some(rel) = lower[search_from..].find("score") {
        let idx = search_from + rel;
        let mut j = idx + "score".len();
        let b = text.as_bytes();
        if j < b.len() && b[j] == b'"' { j += 1; }
        while j < b.len() && (b[j] as char).is_ascii_whitespace() { j += 1; }
        if j < b.len() && (b[j] == b':' || b[j] == b'=') {
            j += 1;
            while j < b.len() && (b[j] as char).is_ascii_whitespace() { j += 1; }
            let start = j;
            while j < b.len() && b[j].is_ascii_digit() { j += 1; }
            if j > start {
                return text[start..j].parse::<f64>().ok();
            }
        }
        search_from = idx + 1;
    }
    None
}
```
